parameters.jsCode:
// Extraer y filtrar datos de Meta WhatsApp Cloud API
const body = $input.item.json.body || $input.item.json;

// Validar si contiene un mensaje entrante (ignorar estados de lectura/entrega)
if (body.entry && body.entry[0]?.changes[0]?.value?.messages) {
  const value = body.entry[0].changes[0].value;
  const message = value.messages[0];
  const contact = value.contacts ? value.contacts[0] : {};

  let messageText = '';
  if (message.type === 'text') {
    messageText = message.text.body;
  } else if (message.type === 'interactive') {
    messageText = message.interactive.button_reply?.title || message.interactive.list_reply?.title || '';
  }

  if (!messageText) {
    return []; // Ignorar audios/stickers o manejar según se requiera
  }

  return {
    json: {
      phoneNumberId: value.metadata.phone_number_id,
      fromNumber: message.from,
      customerName: contact.profile?.name || 'Cliente',
      messageId: message.id,
      messageText: messageText,
      timestamp: message.timestamp
    }
  };
}

return []; // Salir si es sólo notificación de estatus (sent, delivered, read)

